 * Text is composed of blocks separated by blank lines (heading, sections).
 * A block that fits in one message is never split. When the next block would
 * not fit in the current message, it starts a new one and the separator at
 * the break belongs to neither message. A block longer than limit is split
 * between its lines. A single line longer than limit is cut into consecutive
 * pieces of exactly limit characters, the last holding the remainder.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  let currentBuffer: string[] = [];
  let currentLength = 0;

  const tryAddBlock = (block: string): boolean => {
    if (currentLength === 0) {
      if (block.length <= limit) {
        currentBuffer.push(block);
        currentLength = block.length;
        return true;
      }
      return false;
    }
    if (currentLength + block.length <= limit) {
      currentBuffer.push(block);
      currentLength += block.length;
      return true;
    }
    return false;
  };

  for (const block of blocks) {
    if (block.length === 0) continue;

    const fitsAsIs = block.length <= limit;
    if (fitsAsIs) {
      if (tryAddBlock(block)) {
        continue;
      }
      if (currentBuffer.length > 0 || currentLength > 0) {
        messages.push(currentBuffer.join('\n\n'));
        currentBuffer = [];
        currentLength = 0;
      }
      currentBuffer.push(block);
      currentLength = block.length;
    } else {
      if (currentBuffer.length > 0 || currentLength > 0) {
        messages.push(currentBuffer.join('\n\n'));
        currentBuffer = [];
        currentLength = 0;
      }
      const splitLines = block.split('\n');
      let remaining = block;
      for (const line of splitLines) {
        const isLast = line === remaining;
        const pieces = line.slice(0, limit);
        remaining = line.slice(limit);
        if (remaining.length === 0 && isLast) break;
        currentBuffer.push(pieces);
        currentLength += pieces.length;
        if (remaining.length > 0) {
          currentBuffer.push(remaining);
          currentLength += remaining.length;
          remaining = '';
        }
      }
      if (remaining !== block) {
        if (currentBuffer.length === 0 && currentLength === 0) {
          continue;
        }
        if (currentBuffer.length > 0 || currentLength > 0) {
          messages.push(currentBuffer.join('\n\n'));
          currentBuffer = [];
          currentLength = 0;
        }
      }
    }
  }

  if (currentBuffer.length > 0 || currentLength > 0) {
    messages.push(currentBuffer.join('\n\n'));
  }

