 * Text is composed of blocks separated by blank lines (heading, sections).
 * A block that fits in one message is never split. When the next block would
 * not fit in the current message, it starts a new one and the separator at
 * the break belongs to neither message. A block longer than limit is split
 * between its lines. A single line longer than limit is cut into consecutive
 * pieces of exactly limit characters, the last holding the remainder.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  let messagesAsLines: string[][] = [];
  let currentMessageLines: string[] = [];
  let currentLength = 0;

  const pushLineToCurrent = (line: string): boolean => {
    if (line.length + (currentMessageLines.length > 0 ? 2 : 0) > limit) {
      if (currentMessageLines.length > 0) {
        return false;
      }
    }
    currentMessageLines.push(line);
    currentLength += line.length + (currentMessageLines.length > 1 ? 1 : 0);
    return true;
  };

  for (const block of blocks) {
    if (block.length === 0) continue;

    const lines = block.split('\n');
    let canFitAll = true;
    for (const line of lines) {
      if (!pushLineToCurrent(line)) {
        canFitAll = false;
        break;
      }
    }

    if (canFitAll) {
      // Block fits entirely in current message
      if (messages.length === 0) {
        // First block
        messagesAsLines.push(currentMessageLines);
      } else {
        // Add separator before next message
        if (messagesAsLines.length > 0 && messagesAsLines[messagesAsLines.length - 1].length > 0) {
          messagesAsLines[messagesAsLines.length - 1].push('');
        }
        messagesAsLines.push(currentMessageLines);
      }
      currentMessageLines = [];
      currentLength = 0;
    } else {
      // Block doesn't fit entirely - must split
      const splitableLines: string[][] = [];
      for (const line of lines) {
        if (line.length <= limit) {
          splitableLines.push([line]);
        } else {
          // Split long line into fixed-size pieces
