          for (let i = 0; i < line.length; i += limit) {
            pieces.push(line.slice(i, i + limit));
          }
          splitableLines.push(pieces);
        }
      }

      // Push as many lines as possible to current message, then start new
      for (const pieceLines of splitableLines) {
        for (const piece of pieceLines) {
