          messagesAsLines.push(currentMessageLines);
        }
        currentMessageLines = pieceLines;
        currentLength = 0;
      }
    }
  }

  if (messagesAsLines.length === 0) {
    return [];
  }

  const result: string[] = [];
  for (const lines of messagesAsLines) {
    if (lines.length > 0) {
      result.push(lines.join('\n'));
    }
  }

  return result;
}

