input.newString:
/**
 * Split a digest message text into chunks that fit within the character limit.
 * Text is composed of blocks separated by blank lines (heading, sections).
 * A block that fits in one message is never split. When the next block would
 * not fit in the current message, it starts a new one and the separator at
 * the break belongs to neither message. A block longer than limit is split
 * between its lines. A single line longer than limit is cut into consecutive
 * pieces of exactly limit characters, the last holding the remainder.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  let acc: string[] = [];
  let len = 0;

  /** Try to add a block. Returns whether it was added. */
  function tryAdd(b: string): boolean {
    if (len + b.length <= limit) {
      acc.push(b);
      len += b.length;
      return true;
    }
    return false;
  }

  function emit(): void {
    if (acc.length > 0) {
      messages.push(acc.join('\n\n'));
      acc.length = 0;
      len = 0;
    }
  }

  for (const b of blocks) {
    if (b.length === 0) continue;

    if (b.length <= limit) {
      if (tryAdd(b)) continue;
      emit();
      if (tryAdd(b)) continue;
    }
    // Block is longer than limit - must split into lines
    emit();
    for (const ln of b.split('\n')) {
      if (ln.length === 0) continue;
      if (ln.length > limit) {
        // Split long line into fixed-size pieces
        for (let i = 0; i < ln.length; i += limit) {
          const pc = ln.slice(i, i + limit);
          acc.push(pc);
          len += pc.length;
        }
      } else {
        if (acc.length > 0 && len + ln.length <= limit) {
          acc.push(ln);
          len += ln.length;
        } else {
          emit();
          acc.push(ln);
          len = ln.length;
        }
      }
    }
  }

  emit();
  return messages;
}

