/**
 * Split a digest message text into chunks that fit within the character limit.
 * Text is composed of blocks separated by blank lines (heading, sections).
 * A block that fits in one message is never split. When the next block would
 * not fit in the current message, it starts a new one and the separator at
 * the break belongs to neither message. A block longer than limit is split
 * between its lines. A single line longer than limit is cut into consecutive
 * pieces of exactly limit characters, the last holding the remainder.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  const current = [];
  let currentLength = 0;

  const tryAdd = (block: string): boolean => {
    const separatorOverhead = current.length > 0 ? 0 : 0;
    if (currentLength + separatorOverhead + block.length <= limit) {
      current.push(block);
      currentLength += block.length;
      return true;
    }
    return false;
  };

  const finalize = () => {
    if (current.length > 0) {
      messages.push(current.join('\n\n'));
      current.length = 0;
      currentLength = 0;
    }
  };

  for (const block of blocks) {
    if (block.length === 0) continue;

    if (block.length <= limit) {
      if (currentLength === 0) {
        if (tryAdd(block)) {
          continue;
        }
      } else {
        finalize();
        if (tryAdd(block)) {
          continue;
        }
      }
    }

    // Block is too long for a fresh message - must split into lines
    finalize();
    const lines = block.split('\n');
    const lineAcc: string[] = [];
    let lineAccLength = 0;

    for (const line of lines) {
      if (line.length <= limit) {
        if (lineAcc.length > 0 && lineAcc.length + 1 + line.length <= limit) {
          lineAcc.push('', line);
          lineAccLength += line.length + 1;
        } else {
          lineAcc.push(line);
          lineAccLength += line.length;
        }
      } else {
        // Line exceeds limit - split it up
        const pieces: string[] = [];
        for (let i = 0; i < line.length; i += limit) {
          pieces.push(line.slice(i, i + limit));
        }
        const firstPiece = pieces[0];
        for (let i = 0; i < pieces.length; i++) {
          const p = pieces[i];
          if (p.length < limit) {
            finalize();
          }
          const canAdd = current.length + p.length <= limit;
          if (canAdd) {
            current.push(p);
            currentLength += p.length;
          } else {
            finalize();
            if (lineAcc.length > 0) {
              current.push(lineAcc.join('\n'));
              currentLength += lineAcc.join('\n').length;
            }
            current.push(p);
            currentLength += p.length;
          }
          lineAcc.length = 0;
          lineAccLength = 0;
        }
        finalize();
      }
    }
  }

  finalize();
  return messages;
}

