/**
 * Split a digest message text into chunks that fit within the character limit.
 * Text is composed of blocks separated by blank lines (heading, sections).
 * A block that fits in one message is never split. When the next block would
 * not fit in the current message, it starts a new one and the separator at
 * the break belongs to neither message. A block longer than limit is split
 * between its lines. A single line longer than limit is cut into consecutive
 * pieces of exactly limit characters, the last holding the remainder.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  let buffer: string[] = [];
  let bufferLen = 0;

  /**
   * Try to add a block to the current buffer.
   * Returns true if the block was added, false otherwise.
   */
  function tryAddBlock(block: string): boolean {
    if (bufferLen === 0) {
      if (block.length <= limit) {
        buffer.push(block);
        bufferLen = block.length;
        return true;
      }
      return false;
    }
    if (bufferLen + block.length <= limit) {
      buffer.push(`\n\n${block}`);
      bufferLen += 2 + block.length;
      return true;
    }
    return false;
  }

  for (const block of blocks) {
    if (block.length === 0) continue;

    if (block.length <= limit) {
      if (tryAddBlock(block)) {
        continue;
      }
      // Buffer has content but block doesn't fit; finalize then add
      messages.push(buffer.join(''));
      buffer = [block];
      bufferLen = block.length;
      continue;
    }

    // Block is longer than limit - split into lines
    messages.push(buffer.join(''));
    buffer = [];
    bufferLen = 0;

    const lines = block.split('\n');
    let lineBuffer: string[] = [];
    let lineLen = 0;

    for (const line of lines) {
      if (line.length === 0) {
        if (lineBuffer.length > 0 && lineLen + line.length <= limit) {
          buffer.push(`\n\n`);
          bufferLen += 2;
          lineBuffer = [];
          lineLen = 0;
          continue;
        }
        continue;
      }

      if (line.length <= limit) {
        if (lineBuffer.length === 0) {
          lineBuffer.push(line);
          lineLen = line.length;
        } else if (lineLen + line.length <= limit) {
          lineBuffer.push(`\n${line}`);
          lineLen += 1 + line.length;
        } else {
          if (lineLen < limit) {
            if (bufferLen > 0) {
              buffer.push(`\n\n`);
              bufferLen += 2;
            }
            buffer.push(lineBuffer.join(''));
            bufferLen += lineBuffer.join('').length;
            lineBuffer = [line];
            lineLen = line.length;
          } else if (bufferLen === 0) {
            // Line exceeds limit and buffer is empty
            lineBuffer = [];
            lineLen = 0;
          } else {
            // Line exceeds limit, push accumulated and start fresh
            if (lineLen < limit) {
              if (bufferLen > 0) {
                buffer.push(`\n\n`);
                bufferLen += 2;
              }
              buffer.push(lineBuffer.join(''));
              bufferLen += lineBuffer.join('').length;
            }
            lineBuffer = [line];
            lineLen = line.length;
          }
        }
      } else {
        // Line is longer than limit - split into pieces
        if (lineLen > 0 || bufferLen > 0) {
          if (bufferLen > 0) {
            buffer.push(`\n\n`);
            bufferLen += 2;
          }
          buffer.push(lineBuffer.join(''));
          bufferLen += lineBuffer.join('').length;
        }
        lineBuffer = [];
        lineLen = 0;

        const linePieces = line.slice(0, limit), rest = line.slice(limit);
        buffer.push(linePieces);
        bufferLen += limit;

        if (rest.length > 0) {
          buffer.push(rest);
          bufferLen += rest.length;
        }
      }
    }

    if (lineLen > 0 || lineBuffer.length > 0) {
      if (lineLen + (lineBuffer.length > 1 ? lineBuffer.length - 1 : 0) <= limit) {
        if (lineBuffer.length > 0) {
          buffer.push(`\n\n${lineBuffer.join('\n')}`);
          bufferLen += 2 + lineBuffer.join('\n').length;
        }
      }
    }
  }

  if (bufferLen > 0) {
    messages.push(buffer.join(''));
  }

  return messages;
}

