input.newString:
/**
 * Split a digest message text into chunks that fit within the character limit.
 * Text is composed of blocks separated by blank lines (heading, sections).
 * A block that fits in one message is never split. When the next block would
 * not fit in the current message, it starts a new one and the separator at
 * the break belongs to neither message. A block longer than limit is split
 * between its lines. A single line longer than limit is cut into consecutive
 * pieces of exactly limit characters, the last holding the remainder.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const lines = text.split('\n').filter((l, idx) => idx === 0 || text[idx === 0 ? 0 : text.lastIndexOf('\n', idx - 1) + 2] === '\n\n');
  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  let msgLines: string[] = [];
  let msgLen = 0;

  function emitMessage(): void {
    if (msgLines.length > 0) {
      messages.push(msgLines.join('\n'));
      msgLines = [];
      msgLen = 0;
    }
  }

  function tryAddLines(lineSegments: string[]): void {
    for (const seg of lineSegments) {
      if (seg.length === 0) continue;
      if (msgLen + seg.length <= limit) {
        msgLines.push(seg);
        msgLen += seg.length;
      } else {
        const line = seg;
        for (let i = 0; i < line.length; i += limit) {
          const pc = line.slice(i, Math.min(i + limit, line.length));
          msgLines.push(pc);
          msgLen += pc.length;
        }
      }
    }
  }

  for (const block of blocks) {
    if (block.length === 0) continue;
    const fits = block.length <= limit;

    if (!fits) {
      emitMessage();
      tryAddLines([block]);
      continue;
    }

    if (msgLen === 0) {
      msgLines.push(block);
      msgLen = block.length;
      continue;
    }

    if (msgLen + block.length <= limit) {
      msgLines.push(block);
      msgLen += block.length;
    } else {
      emitMessage();
      msgLines.push(block);
      msgLen = block.length;
    }
  }

  if (msgLines.length > 0) {
    messages.push(msgLines.join('\n'));
  }

  return messages;
}

input.oldString:
/**
 * Split a digest message text into chunks that fit within the character limit.
 * Text is composed of blocks separated by blank lines (heading, sections).
 * A block that fits in one message is never split. When the next block would
 * not fit in the current message, it starts a new one and the separator at
 * the break belongs to neither message. A block longer than limit is split
 * between its lines. A single line longer than limit is cut into consecutive
 * pieces of exactly limit characters, the last holding the remainder.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  let msgChunks: string[] = [];
  let msgLen = 0;

  /**
   * If msg is full, emit it and start fresh with the block.
   * If block doesn't fit in a new message, split it by lines.
   */
  function startNewMessageWithBlock(block: string): void {
    if (msgChunks.length > 0) {
      messages.push(msgChunks.join('\n\n'));
      msgChunks = [];
      msgLen = 0;
    }
    // Now add block to fresh message (by lines if needed)
    const lines = block.split('\n');
    for (const line of lines) {
      if (line.length === 0) continue;
      if (line.length <= limit) {
        const fits = msgLen + line.length <= limit;
        if (fits) {
          msgChunks.push(line);
          msgLen += line.length;
        } else {
          // line exceeds remaining space - split line
          for (let i = 0; i < line.length; i += limit) {
            if (msgLen > 0) {
              // push previous accumulated line
              msgChunks.push(msgChunks.shift()!);
              msgLen -= msgChunks.length > 0 ? msgChunks.reduce((s, c) => s + c.length, 0) : 0;
              const prev = msgChunks.pop()!;
              if (msgChunks.length === 0) {
                msgLen = 0;
              } else {
                const remIdx = msgChunks.findIndex((c, idx) => idx === 0);
                msgChunks[remIdx] = prev;
                msgLen += prev.length;
              }
            }
            const piece = line.slice(i, i + limit);
            msgChunks.push(piece);
            msgLen += piece.length;
          }
          continue;
        }
      } else {
        // line itself exceeds full limit
        for (let i = 0; i < line.length; i += limit) {
          const piece = line.slice(i, i + limit);
          if (msgChunks.length === 0) {
            msgChunks.push(piece);
            msgLen += piece.length;
          } else {
            msgChunks.shift();
            msgChunks.push(piece);
          }
        }
      }
    }
  }

  for (const block of blocks) {
    if (block.length === 0) continue;
    const fits = block.length <= limit;
    if (msgLen === 0) {
      // Fresh message
      if (fits) {
        msgChunks.push(block);
        msgLen = block.length;
      } else {
        // Doesn't fit at all - must split into lines and push directly
        startNewMessageWithBlock(block);
      }
      continue;
    }
    if (fits) {
      msgChunks.push(block);
      msgLen += block.length;
      continue;
    }
    startNewMessageWithBlock(block);
  }

  if (msgChunks.length > 0) {
    messages.push(msgChunks.join('\n\n'));
  }

  return messages;
}

