input.newString:
/**
 * Split a digest message text into chunks that fit within the character limit.
 * Text is composed of blocks separated by blank lines. A block that fits in one
 * message is never split. When the next block would not fit in the current message,
 * it starts a new one (block separators at message boundaries belong to neither message).
 * A block longer than limit is split between its lines. A single line longer than
 * limit is cut into consecutive pieces of exactly limit characters, the last holding the remainder.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  let msgLines: string[] = [];
  let msgLen: number = 0;

  const addLines = (lineSegments: string[]): void => {
    for (const seg of lineSegments) {
      if (seg.length === 0) continue;
      if (msgLen + seg.length <= limit) {
        msgLines.push(seg);
        msgLen += seg.length;
      } else {
        for (let i = 0; i < seg.length; i += limit) {
          const pc = seg.slice(i, Math.min(i + limit, seg.length));
          msgLines.push(pc);
          msgLen += pc.length;
        }
      }
    }
  };

  const startNewMsg = (): void => {
    if (msgLines.length > 0) {
      messages.push(msgLines.join('\n'));
      msgLines = [];
      msgLen = 0;
    }
  };

  const emit = (): void => {
    if (msgLines.length > 0) {
      messages.push(msgLines.join('\n'));
      msgLines = [];
      msgLen = 0;
    }
  };

  for (const block of blocks) {
    if (block.length === 0) continue;

    const fits = block.length <= limit;
    const isEmptyMsg = msgLines.length === 0;

    if (!fits) {
      // Block is long, must split into lines first
      startNewMsg();
      const lines = block.split('\n');
      for (const line of lines) {
        if (line.length === 0) continue;
        addLines([line]);
      }
      continue;
    }

    if (isEmptyMsg) {
      addLines([block]);
      continue;
    }

    if (msgLen + block.length <= limit) {
      msgLines.push(block);
      msgLen += block.length;
    } else {
      emit();
      msgLines.push(block);
      msgLen = block.length;
    }
  }

  if (msgLines.length > 0) {
    messages.push(msgLines.join('\n'));
  }

  return messages;
}

