input.newString:
/**
 * Split a digest message text into chunks that fit within the character limit.
 * 
 * Algorithm:
 * - Text is blocks separated by \n\n
 * - Each block is lines separated by \n
 * - Lines >= limit: split into pieces of exactly limit chars (last has remainder)
 * - Lines < limit: add as-is, when sum exceeds limit, split that line
 * - Lines are joined with '\n' within a message
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  // Normalize CRLF to LF, then split on \n\n boundaries
  const textLF = text.replace(/\r\n/g, '\n');
  const blocks = textLF.split(/\n\n+/);

  const messages: string[] = [];
  let msgLines: string[] = [];
  let msgLen: number = 0;

  /** Push a line (or piece of a line) to current message. Splits if needed. */
  const push = (line: string): void => {
    if (line.length === 0) {
      // Skip empty lines (they're \n\n separators between blocks, belong to neither msg)
      return;
    }
    if (msgLen + line.length <= limit) {
      msgLines.push(line);
      msgLen += line.length;
    } else {
      // Line doesn't fit - split it into fixed pieces
      for (let i = 0; i < line.length; i += limit) {
        const pc = line.slice(i, i + limit);
        msgLines.push(pc);
        msgLen += pc.length;
      }
    }
  };

  const emit = (): void => {
    if (msgLines.length > 0) {
      messages.push(msgLines.join('\n'));
      msgLines = [];
      msgLen = 0;
    }
  };

  for (const block of blocks) {
    if (block.length === 0) continue;

    // Check if block is long enough to force a split
    const fits = block.length <= limit;

    if (!fits) {
      // Must split this block into lines first, then process each line
      const lines = block.split('\n');
      push(lines[0]);
      for (let i = 1; i < lines.length; i++) {
        push(lines[i]);
      }
      continue;
    }

    // Block fits in remaining space
    msgLines.push(block);
    msgLen += block.length;
  }

  if (msgLines.length > 0) {
    messages.push(msgLines.join('\n'));
  }

  return messages;
}

