/**
 * Split a digest message text into chunks that fit within the character limit.
 * 
 * Algorithm:
 * - Join blocks with '\n\n' to normalize separators
 * - Split into lines
 * - Lines are units - when they exceed limit, slice them into fixed-size pieces
 * - Push consecutive line pieces until reaching limit, then emit new message
 * - Each message gets lines joined with '\n' as the separator
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  if (text.length <= limit) {
    return [text];
  }

  // Join all blocks with \n\n to normalize, then join with \n and filter line endings
  const normalized = text.replace(/\r\n/g, '\n');
  const parts = normalized.split(/\n\n+/);
  const lines: string[] = [];

  for (const part of parts) {
    if (part.length === 0) continue;
    const lns = part.split('\n');
    for (let i = 0; i < lns.length; i++) {
      lines.push('', lns[i]);
    }
  }

  const messages: string[] = [];
  let msgLines: string[] = [];
  let msgLen: number = 0;

  const addLine = (line: string): void => {
    if (line.length === 0) return;
    if (msgLen + line.length <= limit) {
      msgLines.push(line);
      msgLen += line.length;
    } else {
      // Line too long for current message - split it into pieces
      for (let i = 0; i < line.length; i += limit) {
        const piece = line.slice(i, i + limit);
        msgLines.push(piece);
        msgLen += piece.length;
      }
    }
  };

  const startNewMessage = (): void => {
    if (msgLines.length > 0) {
      messages.push(msgLines.join('\n'));
      msgLines = [];
      msgLen = 0;
    }
  };

  for (const line of lines) {
    if (line.length === 0) continue;
    addLine(line);
  }

  if (msgLines.length > 0) {
    messages.push(msgLines.join('\n'));
  }

  return messages;
}

